#!/usr/bin/env node
/** Generates research/product-scorecard.md from the scored candidates. */
import { writeFileSync } from 'node:fs';
import { CANDIDATES } from './candidates.js';
import { scoreCandidate, rankCandidates, formatScorecard, SUPPLIER_DEPENDENT } from './opportunity-score.js';

const scored = Object.entries(CANDIDATES).map(([name, dims]) => scoreCandidate(name, dims));
const { ranked, interpretation, separation, decisive } = rankCandidates(scored);

const out = [
  '# Product opportunity scorecard',
  '',
  'Generated by `venture/finance/src/build-scorecard.js` from `src/candidates.js`.',
  'Regenerate after changing any score: `node src/build-scorecard.js`.',
  '',
  '## Read the caveat before the ranking',
  '',
  `Three dimensions — **${SUPPLIER_DEPENDENT.join(', ')}** — are unscored for every`,
  'candidate, because no supplier has been contacted and none could be from this',
  `environment. That is **${(ranked[0].missingWeight * 100).toFixed(1)}% of the scoring model left blank.**`,
  '',
  'This is the honest position, and it is worth stating plainly rather than',
  'burying: **the brief asks for a product to be chosen on a weighted score, and a',
  'third of that score cannot be computed without a supplier quote.** Filling those',
  'cells with plausible numbers would produce a ranking that looks decisive and',
  'means nothing.',
  '',
  `> ${interpretation}`,
  '',
  `> **Separation between first and second: ${separation.toFixed(1)} points.** ${decisive}`,
  '',
  '## Ranking on known dimensions',
  '',
  '| # | Candidate | Known score | Normalised | Range once gaps filled |',
  '|---:|---|---:|---:|---|',
  ...ranked.map((r, i) =>
    `| ${i + 1} | ${r.name} | ${r.knownScore.toFixed(1)} / ${(r.knownWeight * 100).toFixed(1)} | **${r.normalisedKnownScore.toFixed(1)}** | ${r.minPossible.toFixed(1)} – ${r.maxPossible.toFixed(1)} |`),
  '',
  '## Full scorecards',
  '',
  ...ranked.map((r) => formatScorecard(r) + '\n'),
].join('\n');

writeFileSync(new URL('../../research/product-scorecard.md', import.meta.url), out);
console.log(`Wrote scorecard. Ranking:`);
ranked.forEach((r, i) => console.log(`  ${i + 1}. ${r.normalisedKnownScore.toFixed(1)}  ${r.name}`));
console.log(`\nSeparation: ${separation.toFixed(1)}`);
console.log(decisive);
